    if (e == null) return;
    const [block, state, nbt] = Array.isArray(e) ? e : [e];
    g.set(x0 + dx, y0 + dy, z0 + dz, block, state, nbt);
    n++;
  })));
  return n;
}

/**
 * Run a build's parts in order so each part can only ADD to what earlier parts built: a write into a cell an earlier
 * part placed (air included, so no carving) is refused, counted, never thrown, so a later part can't knock holes in
 * a wall. Cells set before runParts (the ground) stay writable: farmland and paths may replace grass. With a palette
 * (palette.json, or its object: { roles: { role: [blocks] }, objects: [blocks] }), every block placed outside it is
 * reported. Prints one line per part, writes the reports to `report` (default parts-report.json; null for none) and
 * returns them.
 *   runParts(g, [["shell", shell.build], ["garden", garden.build]], { palette: "palette.json" })
 */
export function runParts(g, list, { palette, log = console.log, report = "parts-report.json" } = {}) {
  const pal = typeof palette === "string" ? (existsSync(palette) ? JSON.parse(readFileSync(palette, "utf8")) : null) : palette;
  const allowed = pal ? new Set([...Object.values(pal.roles ?? {}).flat(), ...(pal.objects ?? [])].map(ns)) : null;
  const owned = new Set(), reports = [], cellsByPart = {};
  for (const [name, build] of list) {
    const mine = new Set(), refused = [], off = new Map();
    const write = (target, x, y, z, block, state, nbt) => {
      const k = `${x},${y},${z}`;
      if (owned.has(k)) { refused.push([x, y, z, ns(block).replace("minecraft:", ""), target.blockAt(x, y, z).replace("minecraft:", "")]); return; }
      const b = ns(block);
      if (allowed && b !== "minecraft:air" && b !== "minecraft:cave_air" && !allowed.has(b)) off.set(b, (off.get(b) ?? 0) + 1);
      target.set(x, y, z, block, state, nbt);
      mine.add(k);
    };
    const view = new Proxy(g, {
      get(target, prop) {
        if (prop === "set") return (x, y, z, block, state, nbt) => { write(target, x, y, z, block, state, nbt); return view; };
        if (prop === "unset") return (x, y, z) => { write(target, x, y, z, "minecraft:air"); return view; };
        if (prop === "fill") return (a, b, block, state) => {
          for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
            for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
              for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) write(target, x, y, z, block, state);
          return view;
        };
        const v = Reflect.get(target, prop);
        return typeof v === "function" ? v.bind(target) : v;
      },
    });
    build(view);
    for (const k of mine) owned.add(k);
    if (process.env.MCD_PARTS_CELLS) cellsByPart[name] = [...mine].map((k) => { const c = g.get(...k.split(",").map(Number)); return [k, c ? c.block.replace("minecraft:", "") + (c.state ? JSON.stringify(c.state) : "") : "air"]; });
    const r = { part: name, placed: mine.size, refused: refused.length, refusedAt: refused.slice(0, 8),
      offPalette: [...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n}`) };
    reports.push(r);
    log(`part ${name}: ${r.placed} placed` +
      (r.refused ? `; REFUSED ${r.refused} writes into earlier parts (x,y,z wanted had: ${r.refusedAt.map((p) => `${p[0]},${p[1]},${p[2]} ${p[3]} ${p[4]}`).join("; ")})` : "") +
      (r.offPalette.length ? `; OFF-PALETTE: ${r.offPalette.join(", ")}` : ""));
  }
  if (report) writeFileSync(report, JSON.stringify(reports, null, 1));
  // $MCD_PARTS_CELLS=<file>: every part's cells, for measuring how much code each block cost (lab token audits)
  if (process.env.MCD_PARTS_CELLS) writeFileSync(process.env.MCD_PARTS_CELLS, JSON.stringify(cellsByPart));
  return reports;
}

// ---- shape brushes (curved forms; massing) — the model picks parameters, code draws the form ---------------------
export * from "./shapes-curved.mjs";
export * from "./shapes-massing.mjs";

// ---- landscaping brushes (terrain, strata, boulders, water, trees, paths, bridges) — see references/landscaping.md --
export * from "./terrain.mjs";

// ---- roofs by style name (gable, hip, pyramid, mansard, gambrel, flat-parapet, shed, dutch-gable) — references/roofs.md
export * from "./roofs.mjs";

// ---- facade brushes (signage, pilasters, surrounds, glazing, fixtures, planters) — references/detail-language.md -----
// Each is a function on a grid (writes only where it may: air for projections, plain wall for in-place trim; returns
// { cells, skipped, notes, info }) and a B.* twin that returns the plan as g.set argument lists, unchecked.
// at = a wall cell (bottom-left of the band / opening as seen from outside), face = the side it looks out of.
import { commitGrid, lookGrid, tuples } from "./brush-core.mjs";
import { plaquePlan, signboardPlan, buntingPlan } from "./brush-sign.mjs";
import { pilasterPlan } from "./brush-pilaster.mjs";
import { surroundPlan, glazingPlan } from "./brush-surround.mjs";
import { fixturePlan, planterPlan } from "./brush-fixture.mjs";
const withLook = (g, o) => ({ ...o, look: lookGrid(g), dataVersion: o?.dataVersion ?? g.dataVersion });
/** Lettering in a band: plaque(g, "LEAGUE HALL", { at, face, width, height, letter?, material?, frame?, style?, relief? }) */
export const plaque = (g, text, o) => commitGrid(g, plaquePlan(text, withLook(g, o)), o);
/** A shop sign: signboard(g, "BAKERY", { at, face, mode: "wall"|"hanging", width?, height?, wood? }) */
export const signboard = (g, text, o) => commitGrid(g, signboardPlan(text, withLook(g, o)), o);
/** Banners along a row: bunting(g, { from, to, face, colors?, every?, pattern? }) */
export const bunting = (g, o) => commitGrid(g, buntingPlan(withLook(g, o)), o);
/** A profiled pilaster: pilaster(g, { at, face, height, width?, out?, material?, profile?, shoulder? }) */
export const pilaster = (g, o) => commitGrid(g, pilasterPlan(o), o);
/** An opening surround: surround(g, { at, face, width, height, preset?, trim?, keystone?, reveal?, door?, arch? }) */
export const surround = (g, o) => commitGrid(g, surroundPlan(withLook(g, o)), o);
/** Glazing: glazing(g, { at, face, width, height, preset: grid|shopfront|transom|sidelights, frame?, door? }) */
export const glazing = (g, o) => commitGrid(g, glazingPlan(withLook(g, o)), o);
/** A light fitting: fixture(g, { at, face, mount: bracket|arm|top|hang, lamp? }) */
export const fixture = (g, o) => commitGrid(g, fixturePlan(withLook(g, o)), o);
/** A planter: planter(g, { at, face, width, kind: box|ground, depth?, plants? }) */
export const planter = (g, o) => commitGrid(g, planterPlan(withLook(g, o)), o);
Object.assign(B, {
  plaque: (text, o) => tuples(plaquePlan(text, o)), signboard: (text, o) => tuples(signboardPlan(text, o)), bunting: (o) => tuples(buntingPlan(o)),
  pilaster: (o) => tuples(pilasterPlan(o)), surround: (o) => tuples(surroundPlan(o)), glazing: (o) => tuples(glazingPlan(o)),
  fixture: (o) => tuples(fixturePlan(o)), planter: (o) => tuples(planterPlan(o)),
});
/** Run detail-language rules from code (weather / vary presets, treatments on every opening): returns { grid, report }. */
export { applyDetail as paint } from "./detail-lang.mjs";
----ROOMS
// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// Rooms a player can walk into: a flood fill over the cells a player can stand in (two passable cells over a floor),
// stepping up one block (a jump, with headroom) or down up to three, through doors and gates, from the entrance
// (or from every standable cell on the site's edge). Each room is a box of its inner air; the report says how many of
// its standable cells were reached, so a room with no way in, or furniture that walls the floor off, shows up.
//   walkReport(grid, { rooms: [{ name, box: [x0,y0,z0,x1,y1,z1] }], entrance: [x,y,z] })
const strip = (n) => String(n).replace(/^minecraft:/, "");
const PASS = /air$|carpet|redstone_wire|(^|_)rail$|pressure_plate|torch|_button|lever|flower$|tulip|grass$|fern$|sapling|snow$|vine|ladder|_sign$|banner$|tripwire|candle$|light$|structure_void|_door$|fence_gate$|bush$|poppy|dandelion|orchid|allium|bluet|daisy|cornflower|lily_of|wither_rose|azalea$|moss_carpet/;
const k = (x, y, z) => `${x},${y},${z}`;

export function walkReport(grid, { rooms = [], entrance } = {}) {
  const [sx, sy, sz] = grid.size;
  const pass = (x, y, z) => !grid.inBounds(x, y, z) ? y >= 0 && y < sy + 2 : PASS.test(strip(grid.blockAt(x, y, z)));
  const floor = (x, y, z) => grid.inBounds(x, y, z) && !pass(x, y, z);
  const stand = (x, y, z) => grid.inBounds(x, y, z) && pass(x, y, z) && pass(x, y + 1, z) && floor(x, y - 1, z);
  let start = [];
  if (entrance && stand(...entrance)) start = [entrance];
  else {
    for (let x = 0; x < sx; x++) for (let z = 0; z < sz; z++) {
      if (x !== 0 && z !== 0 && x !== sx - 1 && z !== sz - 1) continue;
      for (let y = 1; y < sy; y++) if (stand(x, y, z)) { start.push([x, y, z]); break; }
    }
  }
  const seen = new Set(start.map((p) => k(...p))), q = [...start];
  while (q.length) {
    const [x, y, z] = q.pop();
    for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nx = x + dx, nz = z + dz;
      for (const dy of [0, 1, -1, -2, -3]) {
        const ny = y + dy;
        if (seen.has(k(nx, ny, nz)) || !stand(nx, ny, nz)) continue;
        if (dy === 1 && !pass(x, y + 2, z)) continue;                         // a jump needs headroom where you start
        if (dy < 0 && ![...Array(-dy).keys()].every((i) => pass(nx, y - i, nz) && pass(nx, y + 1 - i, nz))) continue;
        seen.add(k(nx, ny, nz)); q.push([nx, ny, nz]);
        break;                                                                // one landing per column step
      }
    }
  }
  const out = rooms.map(({ name, box }) => {
    const [x0, y0, z0, x1, y1, z1] = box;
    let standable = 0, reached = 0;
    const unreached = [];
    for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++)
      for (let y = Math.min(y0, y1); y <= Math.max(y0, y1); y++)
        for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++) {
          if (!stand(x, y, z)) continue;
          standable++;
          if (seen.has(k(x, y, z))) reached++;
          else unreached.push([x, y, z]);
        }
    const verdict = standable === 0 ? "no floor to stand on" : reached === 0 ? "UNREACHABLE: no way in" :
      reached < standable * 0.6 ? "PARTLY BLOCKED: furniture or walls cut the floor off" : "ok";
    return { name, standable, reached, verdict, ...(unreached.length && reached ? { unreached: unreached.slice(0, 24) } : {}) };
  });
  const report = { start: start.length, reachedCells: seen.size, rooms: out, ok: out.every((r) => r.verdict === "ok") };
  return Object.defineProperty(report, "reached", { value: (x, y, z) => seen.has(k(x, y, z)) });   // not printed
}

/**
 * A room's floor as a character grid to draw furniture into (the input side of build.mjs layers()): '#' wall or solid,
 * 'D' a doorway, 'W' a window in the wall, 'o' something already standing on the floor (furniture, a lamp), '.' free
 * floor a player can stand on, ' ' outside. Rows run along +x, successive rows along +z, from the box's corner, so the
 * grid can be copied into layers(g, [x0, y, z0], legend, rows) with characters swapped for furniture.
 */
export function floorPlan(grid, { name, box }) {
  const [x0, y0, z0, x1, y1, z1] = [Math.min(box[0], box[3]), Math.min(box[1], box[4]), Math.min(box[2], box[5]), Math.max(box[0], box[3]), Math.max(box[1], box[4]), Math.max(box[2], box[5])];
  const pass = (x, y, z) => !grid.inBounds(x, y, z) || PASS.test(strip(grid.blockAt(x, y, z)));
  let fy = y0;                                                     // the floor level: the lowest y with standable cells
  for (let y = y0; y <= y1; y++) { let any = false; for (let x = x0; x <= x1 && !any; x++) for (let z = z0; z <= z1; z++) if (pass(x, y, z) && grid.inBounds(x, y - 1, z) && !pass(x, y - 1, z)) { any = true; break; } if (any) { fy = y; break; } }
  const rows = [];
  for (let z = z0 - 1; z <= z1 + 1; z++) {
    let row = "";
    for (let x = x0 - 1; x <= x1 + 1; x++) {
      const inside = x >= x0 && x <= x1 && z >= z0 && z <= z1;
      const b = strip(grid.blockAt(x, fy, z)), up = strip(grid.blockAt(x, fy + 1, z));
      if (/_door$/.test(b) || (!inside && pass(x, fy, z) && pass(x, fy + 1, z))) row += inside ? "." : "D";
      else if (!inside) row += /glass|pane/.test(up) || /glass|pane/.test(b) ? "W" : "#";
      else if (pass(x, fy, z)) row += pass(x, fy + 1, z) && !pass(x, fy - 1, z) ? "." : " ";
      else row += "o";
    }
    rows.push(row);
  }
  return { name, floorY: fy, origin: [x0 - 1, fy, z0 - 1], rows };
}

export function floorPlanText(plans) {
  const out = ["# floor plans: '#' wall  'D' doorway  'W' window  'o' already there  '.' free floor. Rows run along +x,",
    "# successive rows along +z; the first row and column are the walls around the room. Draw furniture into a copy and",
    "# place it with layers(g, origin, legend, rows) from the build library (characters not in the legend are skipped)."];
  for (const p of plans) {
    out.push("", `## ${p.name}: floor y=${p.floorY}, origin [${p.origin.join(", ")}] (the top-left corner of the grid)`);
    out.push("     " + p.rows[0].split("").map((_, i) => ((p.origin[0] + i) % 10)).join("") + "   <- x mod 10");
    p.rows.forEach((r, i) => out.push(`z${String(p.origin[2] + i).padStart(3)} ${r}`));
  }
  return out.join("\n");
}

